package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class EventWorkflowsBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  String group;try(var db=h.store.open()){PlatformFoundationTest.bind(db);db.update("UPDATE os_clock_policy SET active=0");db.update("UPDATE os_event_flow SET active=0");db.update("UPDATE os_event_run SET state='cancelled' WHERE state='pending'");group=Service.create(db,"sys_user_group",map("short_description","Workflow verification team"),"admin").get("sys_id").toString();db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Event workflows").setExact(true)).press("Enter");page.getByLabel("Record type",new Page.GetByLabelOptions().setExact(true)).selectOption("incident");ServiceOutagesBrowserAcceptance.click(page,"Choose record type");page.getByLabel("Workflow name").fill("New incident action plan <script>");page.getByLabel("Trigger event").selectOption("created");page.getByLabel("Trigger state").selectOption("1");page.getByLabel("Assignment action",new Page.GetByLabelOptions().setExact(true)).selectOption("true");page.getByLabel("Assignment team",new Page.GetByLabelOptions().setExact(true)).selectOption(group);page.getByLabel("Assignee username").fill("admin");page.getByLabel("Task creation action").selectOption("true");page.getByLabel("Task creation team").selectOption(group);page.getByLabel("Task summary").fill("Verify the assigned incident");page.getByLabel("Task details").fill("Inspect the evidence and retain the outcome");page.getByLabel("Task completion required").selectOption("true");page.getByLabel("Parent completion state").selectOption("6");page.getByLabel("Internal note action").selectOption("true");page.getByLabel("Internal note text").fill("Automation created the verification task <script>");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/event-flow-light.png")).setFullPage(true));ServiceOutagesBrowserAcceptance.click(page,"Save event workflow");String flowUrl=page.url();assertThat(page.locator("main")).containsText("New incident action plan <script>");
   java.util.Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"sys_user_group");var restricted=new java.util.LinkedHashMap<>(original);restricted.put("record_roles",map("read",java.util.List.of("agent")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='sys_user_group'",JSON.writeValueAsString(restricted));db.connection.commit();}page.reload();page.getByLabel("Flow availability").selectOption("false");ServiceOutagesBrowserAcceptance.click(page,"Save event workflow");try(var db=h.store.open()){assertEquals(0,db.count("SELECT active FROM os_event_flow WHERE name=?","New incident action plan <script>"));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='sys_user_group'",JSON.writeValueAsString(original));db.connection.commit();}page.getByLabel("Flow availability").selectOption("true");ServiceOutagesBrowserAcceptance.click(page,"Save event workflow");
   page.navigate(h.base()+"/record/incident/new");page.locator("input[name=short_description]").fill("Real browser-triggered action plan");ServiceOutagesBrowserAcceptance.click(page,"Create record →");String recordUrl=page.url();page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Workflow execution history").setExact(true)).press("Enter");assertThat(page.locator("article")).containsText("pending");assertTrue(new WorkWorker(new Store(h.environment)).runOne(System.currentTimeMillis()+1000));page.reload();assertThat(page.locator("article")).containsText("succeeded");assertThat(page.locator("article ol li")).hasCount(3);ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(page.locator("main script")).hasCount(0);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/event-flow-history-dark.png")).setFullPage(true));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("View job and attempts")).press("Enter");assertThat(page.locator("main")).containsText("succeeded");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("View attempt history")).press("Enter");assertThat(page.locator("main")).containsText("succeeded");page.navigate(recordUrl);assertThat(page.locator("main")).containsText("Automation created the verification task <script>");assertThat(page.locator("input[name=assigned_to]")).hasValue("admin");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Coordinate work tasks")).press("Enter");assertThat(page.locator("main")).containsText("Verify the assigned incident");page.navigate(flowUrl);assertThat(page.locator("main")).containsText("only availability may change");page.getByLabel("Flow availability").selectOption("false");ServiceOutagesBrowserAcceptance.click(page,"Save event workflow");assertThat(page.locator("main")).containsText("Disabled");
  }
 }
}
